local PlayingCardMaker = {}
local PRODUCTS = {
    woodcut_deck = { name = "Lesorezna karte", paperCost = 2, inkCost = 1, time = 2, cost = 15, artistry = 40, happiness = 2, description = "Lesorezne karte za navadne igre." },
    hand_painted_deck = { name = "Ročno poslikane karte", paperCost = 2, inkCost = 1, paintCost = 1, time = 4, cost = 40, artistry = 55, prestige = 2, happiness = 3, description = "Ročno poslikane karte z figurami." },
    stencil_deck = { name = "Šablonske karte", paperCost = 2, inkCost = 1, paintCost = 1, silverCost = 1, time = 5, cost = 90, artistry = 70, prestige = 4, happiness = 4, description = "Šablonske karte z natančnimi vzorci." },
    silver_edge_deck = { name = "Srebrnorobne karte", paperCost = 3, silverCost = 1, inkCost = 1, paintCost = 1, time = 7, cost = 220, artistry = 82, prestige = 9, happiness = 5, description = "Srebrnorobne karte za plemiče." },
    gold_edge_deck = { name = "Zlatorobne karte", paperCost = 3, goldCost = 1, silverCost = 1, inkCost = 1, paintCost = 1, time = 10, cost = 480, artistry = 92, prestige = 16, happiness = 7, description = "Zlatorobne karte za visoke plemiče." },
    royal_grand_cards = { name = "Kraljevski veliki karte", paperCost = 5, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, inkCost = 2, paintCost = 2, time = 15, cost = 1400, artistry = 100, prestige = 38, happiness = 12, description = "Velike kraljevske karte z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Igralkarska delavnica", cost = { gold = 240, wood = 120, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    printing_room = { name = "Tiskalnica", cost = { gold = 800, wood = 220, stone = 400, paper = 8 }, upkeep = 20, qualityBonus = 18 },
    gilding_room = { name = "Pozlatnica", cost = { gold = 2100, wood = 350, stone = 600, silver = 25, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_card_atelier = { name = "Kraljevski atelje igralk", cost = { gold = 8800, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 175, qualityBonus = 55, prestigeBonus = 40 },
}
PlayingCardMaker.paperStock = 20; PlayingCardMaker.inkStock = 14; PlayingCardMaker.paintStock = 12; PlayingCardMaker.silverStock = 8; PlayingCardMaker.goldStock = 6; PlayingCardMaker.jewelStock = 6; PlayingCardMaker.pearlStock = 4
PlayingCardMaker.productStock = {}; PlayingCardMaker.buildings = {}; PlayingCardMaker.maker = nil; PlayingCardMaker.activeMaking = {}; PlayingCardMaker.totalProducts = 0; PlayingCardMaker.dayTimer = 0
function PlayingCardMaker.init() PlayingCardMaker.paperStock=20; PlayingCardMaker.inkStock=14; PlayingCardMaker.paintStock=12; PlayingCardMaker.silverStock=8; PlayingCardMaker.goldStock=6; PlayingCardMaker.jewelStock=6; PlayingCardMaker.pearlStock=4; PlayingCardMaker.productStock={}; PlayingCardMaker.buildings={}; PlayingCardMaker.maker=nil; PlayingCardMaker.activeMaking={}; PlayingCardMaker.totalProducts=0; PlayingCardMaker.dayTimer=0; print("[PlayingCardMaker] Royal Playing Card Maker System initialized (6 products, 4 buildings)") end
function PlayingCardMaker.hireMaker(n,s) s=s or math.random(50,90); local c=490+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlayingCardMaker.maker={name=n or ("Igralkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Igralkar najet: %s (spretnost: %d)",PlayingCardMaker.maker.name,s),"success") end; return true end
function PlayingCardMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlayingCardMaker.build(id) local ok,e=PlayingCardMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlayingCardMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlayingCardMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlayingCardMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlayingCardMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.paperCost and PlayingCardMaker.paperStock<(d.paperCost or 0) then return false,"Premalo papirja" end; if d.inkCost and PlayingCardMaker.inkStock<(d.inkCost or 0) then return false,"Premalo črnila" end; if d.paintCost and PlayingCardMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and PlayingCardMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlayingCardMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlayingCardMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlayingCardMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlayingCardMaker.buildings==0 then return false,"Potrebna delavnica" end; if not PlayingCardMaker.maker then return false,"Potreben igralkar" end; return true end
function PlayingCardMaker.make(pt,qty) qty=qty or 1; local ok,e=PlayingCardMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.paperCost then PlayingCardMaker.paperStock=PlayingCardMaker.paperStock-d.paperCost*qty end; if d.inkCost then PlayingCardMaker.inkStock=PlayingCardMaker.inkStock-d.inkCost*qty end; if d.paintCost then PlayingCardMaker.paintStock=PlayingCardMaker.paintStock-d.paintCost*qty end; if d.silverCost then PlayingCardMaker.silverStock=PlayingCardMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlayingCardMaker.goldStock=PlayingCardMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlayingCardMaker.jewelStock=PlayingCardMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlayingCardMaker.pearlStock=PlayingCardMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlayingCardMaker.maker then t=math.max(1,t-math.floor(PlayingCardMaker.maker.skill/12)) end; table.insert(PlayingCardMaker.activeMaking,{id="playingcard_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,artistry=d.artistry or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlayingCardMaker.completeMaking(m) local q=1.0+(PlayingCardMaker.getQualityBonus()/100); if PlayingCardMaker.maker then q=q+(PlayingCardMaker.maker.skill/180) end; q=math.min(2.0,q); PlayingCardMaker.productStock[m.productType]=(PlayingCardMaker.productStock[m.productType] or 0)+m.quantity; PlayingCardMaker.totalProducts=PlayingCardMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlayingCardMaker.maker then PlayingCardMaker.maker.itemsMade=PlayingCardMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then PlayingCardMaker.maker.skill=math.min(100,PlayingCardMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Karte izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"playingcard.completed",{productName=m.productName,artistry=m.artistry,prestige=m.prestige,happiness=m.happiness}) end end
function PlayingCardMaker.update(dt) if not _G.state then return end; PlayingCardMaker.dayTimer=PlayingCardMaker.dayTimer+dt; if PlayingCardMaker.dayTimer>=30 then PlayingCardMaker.dayTimer=0; for i=#PlayingCardMaker.activeMaking,1,-1 do local m=PlayingCardMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlayingCardMaker.completeMaking(m); table.remove(PlayingCardMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlayingCardMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlayingCardMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlayingCardMaker.getStats() return {paperStock=PlayingCardMaker.paperStock,inkStock=PlayingCardMaker.inkStock,paintStock=PlayingCardMaker.paintStock,silverStock=PlayingCardMaker.silverStock,goldStock=PlayingCardMaker.goldStock,jewelStock=PlayingCardMaker.jewelStock,pearlStock=PlayingCardMaker.pearlStock,productStock=PlayingCardMaker.productStock,numBuildings=#PlayingCardMaker.buildings,hasMaker=PlayingCardMaker.maker~=nil,makerName=PlayingCardMaker.maker and PlayingCardMaker.maker.name or "—",makerSkill=PlayingCardMaker.maker and PlayingCardMaker.maker.skill or 0,activeMaking=#PlayingCardMaker.activeMaking,totalProducts=PlayingCardMaker.totalProducts} end
return PlayingCardMaker
